#!/usr/bin/env python3
import subprocess
from pathlib import Path

HERE = Path(__file__).resolve().parent

# Reuse the qualified two-pass fast block:
#   E1 -> (ne,phi)1 -> E2 -> (ne,phi)2
# generated by the previous diagnostic, then restore the outer coupling to
# TIMESTEP_BEGIN so the fast block executes BEFORE the parent heavy solve.
subprocess.run(["python3", "prepare_heavy_energy_ep_two_corrections.py"], cwd=HERE, check=True)

parent_path = HERE / "heavy_parent.i"
fast_path = HERE / "fast_child.i"
ep_path = HERE / "electron_poisson_stage.i"

parent = parent_path.read_text(encoding="utf-8")

# prepare_heavy_energy_ep_once.py deliberately changed all three coupling flags
# to TIMESTEP_END for the heavy-first experiment.  Reverse exactly those three
# flags here.  In the parent architecture this gives:
#   1) transfer H^n -> fast child,
#   2) run fast fixed-point corrections at TIMESTEP_BEGIN,
#   3) transfer corrected phi -> potential_fast,
#   4) solve heavy H^n -> H^(n+1) over the physical 1 ns parent step.
old_flag = "execute_on = TIMESTEP_END"
count = parent.count(old_flag)
if count < 3:
    raise RuntimeError(f"expected at least 3 TIMESTEP_END coupling flags, found {count}")

# Restrict replacement to the outer coupling block only, so diagnostics and
# postprocessors keep their original schedules.
ma_start = parent.find("[MultiApps]\n")
exec_start = parent.find("[Executioner]\n", ma_start)
if ma_start < 0 or exec_start < 0:
    raise RuntimeError("outer MultiApps/Executioner coupling region not found")
region = parent[ma_start:exec_start]
region_count = region.count(old_flag)
if region_count != 3:
    raise RuntimeError(f"expected 3 TIMESTEP_END flags in outer coupling region, found {region_count}")
region = region.replace(old_flag, "execute_on = TIMESTEP_BEGIN")
parent = parent[:ma_start] + region + parent[exec_start:]

parent = parent.replace("output_correction/heavy", "output_fast_first/heavy")
parent_path.write_text(parent, encoding="utf-8")

fast = fast_path.read_text(encoding="utf-8")
fast = fast.replace("output_correction/energy", "output_fast_first/energy")
fast_path.write_text(fast, encoding="utf-8")

ep = ep_path.read_text(encoding="utf-8")
ep = ep.replace("output_correction/electron_poisson", "output_fast_first/electron_poisson")
ep_path.write_text(ep, encoding="utf-8")

print("prepared fast-first two-correction then heavy diagnostic")
print("  fast pass 1: energy -> electron+Poisson")
print("  fast pass 2: energy -> electron+Poisson")
print("  heavy input state during fast passes: H^n frozen")
print("  corrected potential is returned before heavy solve")
print("  heavy physical advance: H^n -> H^(n+1), dt = 1.0 ns")
print("  correction passes do NOT advance physical time")
